/// The Krishna-Standart mass-transfer rate matrix.
///
/// All arguments are SI magnitudes. See the module documentation for why.
#[pyfunction]
#[pyo3(signature = (components, reaction_components, reaction_lengths, reaction_coefficients, rate_factors, equilibrium_constants, fractions, molar_masses, density, inter_fractions, inter_density, diffusion))]
#[pyo3(
    text_signature = "(components, reaction_components, reaction_lengths, reaction_coefficients, rate_factors, equilibrium_constants, fractions, molar_masses, density, inter_fractions, inter_density, diffusion)"
)]
#[allow(clippy::too_many_arguments)] // The signature is the spec's declared inputs.
pub fn kinetics(
    py: Python<'_>,
    components: Vec<String>,
    reaction_components: Vec<String>,
    reaction_lengths: Vec<f64>,
    reaction_coefficients: Vec<f64>,
    rate_factors: Vec<f64>,
    equilibrium_constants: Vec<f64>,
    fractions: Vec<f64>,
    molar_masses: Vec<f64>,
    density: f64,
    inter_fractions: Vec<f64>,
    inter_density: f64,
    diffusion: Vec<f64>,
) -> PyResult<crate::transport_gen::PyKineticsResult> {
    let components_refs: Vec<&str> = components.iter().map(String::as_str).collect();
    let reaction_components_refs: Vec<&str> =
        reaction_components.iter().map(String::as_str).collect();
    azoth_reactions::kinetics::kinetics(
        &components_refs,
        &reaction_components_refs,
        &reaction_lengths,
        &reaction_coefficients,
        &rate_factors,
        &equilibrium_constants,
        &fractions,
        &molar_masses,
        density,
        &inter_fractions,
        inter_density,
        &diffusion,
    )
    .map(|r| crate::transport_gen::PyKineticsResult::from(&r))
    .map_err(|e| to_pyerr(py, e))
}

